import{_ as t,o as s,c as a,ag as o}from"./chunks/framework.Nx1zvZTu.js";const u=JSON.parse('{"title":"The API server","description":"","frontmatter":{},"headers":[],"relativePath":"guide/server.md","filePath":"guide/server.md"}'),i={name:"guide/server.md"};function n(r,e,d,c,h,l){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="the-api-server" tabindex="-1">The API server <a class="header-anchor" href="#the-api-server" aria-label="Permalink to &quot;The API server&quot;">​</a></h1><p>machinable ships an HTTP + WebSocket server that exposes a project&#39;s interfaces to remote clients: a JSON control plane, a binary data plane, the config/identity <a href="./storage.html">index</a> with search, and the <a href="./execution.html">execution</a> lifecycle. Each interface decides what its bytes and method calls mean; the server stays use-case agnostic. (The <a href="/mcp/overview.html">MCP</a> is a curated, agent-facing facade over this same surface.)</p><h2 id="launching" tabindex="-1">Launching <a class="header-anchor" href="#launching" aria-label="Permalink to &quot;Launching&quot;">​</a></h2><p>The server is itself an interface (<code>machinable.server</code>). Launch it with the <a href="./cli.html">CLI</a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">machinable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> machinable.server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project=&quot;/path/to/project&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --launch</span></span></code></pre></div><p>Its <code>Config</code> controls the bind and the security surface:</p><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>host</code> / <code>port</code></td><td><code>127.0.0.1</code> / <code>8000</code></td><td>bind address</td></tr><tr><td><code>console</code></td><td><code>None</code> (auto)</td><td>attach the <a href="#the-console">console</a> when launched from a terminal</td></tr><tr><td><code>api_token</code></td><td><code>None</code></td><td>bearer token required for requests and WebSocket upgrades</td></tr><tr><td><code>oidc_issuer</code></td><td><code>None</code></td><td>accept access tokens from this OpenID Connect provider (see <a href="#signing-requests-with-an-identity-provider">below</a>)</td></tr><tr><td><code>project</code></td><td><code>None</code></td><td>the default project a request binds to</td></tr><tr><td><code>project_roots</code></td><td><code>None</code></td><td>extra roots that may be opened per request</td></tr><tr><td><code>python_allowlist</code></td><td><code>None</code></td><td>interpreters a request may use besides a project&#39;s own <code>.venv</code> (see <a href="#process-isolated-workers">workers</a>)</td></tr><tr><td><code>project_default_python</code></td><td><code>False</code></td><td>serve a request that names a project under <code>project_roots</code>, and no interpreter, by that project&#39;s own <code>.venv</code></td></tr><tr><td><code>worker_start_seconds</code></td><td><code>30</code></td><td>how long a worker may take to start</td></tr><tr><td><code>worker_idle_seconds</code></td><td><code>None</code></td><td>end a worker idle this long (started again on its next request)</td></tr><tr><td><code>enable_source_api</code></td><td><code>False</code></td><td>allow writing project <code>.py</code> files (remote code execution, off by default)</td></tr><tr><td><code>source_token</code></td><td><code>None</code></td><td>token required for the source-editing API, sent as <code>X-Machinable-Source-Token</code></td></tr></tbody></table><p>Clients authenticate with a bearer header instead of cookies, so the API&#39;s CORS policy allows any origin by default and grants credentialed requests (cookies, HTTP auth) only to explicitly listed origins (<code>create_app(allow_origins=[...])</code>).</p><p>Source writes need the <code>source_token</code> in <code>X-Machinable-Source-Token</code>, beside the server&#39;s own auth in <code>Authorization</code>, so a <code>source_token</code> different from <code>api_token</code> (or an OIDC token) works. <code>Authorization: Bearer &lt;source_token&gt;</code> is still accepted when the server has no other auth, or when <code>source_token</code> is unset and falls back to <code>api_token</code>.</p><h3 id="with-a-storage" tabindex="-1">With a storage <a class="header-anchor" href="#with-a-storage" aria-label="Permalink to &quot;With a storage&quot;">​</a></h3><p>Put a <a href="./storage.html">storage</a> (or an index) before the server in the element chain and the server keeps its records there:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">machinable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interface.remotes.s3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> url=s3://my-bucket/lab/machinable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> region=us-east-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  machinable.server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project=&quot;/path/to/project&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --launch</span></span></code></pre></div><p>Here the <a href="/integrations/s3.html">s3 integration</a>, pulled into the project through <code>on_resolve_remotes</code>, makes the bucket the home of every record the server creates. The connections around the launch are re-entered, in order, wherever the server works: each request, the thread that runs a dispatched execution, the cached or running-elsewhere answer to <code>POST /v1/executions</code> (so servers on several machines over one bucket run a request once), each WebSocket connection, and the <a href="#process-isolated-workers">workers</a>. The server itself is only launched in them, not dispatched, so it is no run in the storage. A server started in-process (<code>Server.start()</code>, as a notebook does) takes the storage and index connected around it the same way.</p><h3 id="process-isolated-workers" tabindex="-1">Process-isolated workers <a class="header-anchor" href="#process-isolated-workers" aria-label="Permalink to &quot;Process-isolated workers&quot;">​</a></h3><p>A request or WebSocket for another interpreter (<code>X-Machinable-Python</code> or <code>?python=</code>) is proxied to a worker process on loopback, one per project and interpreter. The interpreter must be the gateway&#39;s own, the project&#39;s own <code>.venv</code>, or listed in <code>python_allowlist</code>. A worker starts in its project&#39;s folder, so the project&#39;s modules import their siblings by name and nothing in the gateway&#39;s folder shadows them.</p><p>The gateway gives each worker a random secret at spawn (in its environment) and the worker refuses every request without it, so other local users cannot call a worker directly or claim an <code>X-Machinable-User</code>. The client&#39;s <code>Authorization</code> is not forwarded to the worker. A request the gateway admitted by OIDC reaches the worker with the verified identity as its <code>X-Machinable-User</code> and the token&#39;s verified claims as <code>X-Machinable-Claims</code>, which the worker trusts only with its secret, so <code>Project.get().claims</code> reads the same in a worker as in-process. A socket is relayed frame by frame (text and binary), the worker&#39;s close code reaches the client, and an OIDC-admitted socket still closes with <code>4401</code> when its token expires.</p><h3 id="several-projects-in-their-own-environments" tabindex="-1">Several projects in their own environments <a class="header-anchor" href="#several-projects-in-their-own-environments" aria-label="Permalink to &quot;Several projects in their own environments&quot;">​</a></h3><p>One server (one port, one identity provider, one <a href="#with-a-storage">storage</a>) can serve many projects side by side, each with its own dependencies, for example two versions of one package checked out next to each other:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">machinable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> machinable.server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project_roots=&#39;[&quot;/srv/projects&quot;]&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  project_default_python=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> worker_idle_seconds=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">600</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --launch</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/srv/projects/</span></span>
<span class="line"><span>  analyses@769e03a5/   .venv/ ...</span></span>
<span class="line"><span>  analyses@1a2b3c4d/   .venv/ ...</span></span></code></pre></div><p>With <code>project_default_python</code>, a client names only the project (<code>X-Machinable-Project: /srv/projects/analyses@769e03a5</code>, or <code>?project=</code>) and the server runs it in that project&#39;s own <code>.venv</code>; a project without one is served in-process. A request that names an interpreter keeps it.</p><p><code>GET /v1/health</code> on the gateway asks each live worker for its own health (briefly; one that does not answer counts 0): <code>executions_active</code> counts the runs in the gateway and in its workers once each (<code>active_executions</code> lists them), and <code>workers</code> names each worker with what runs in it, so an idle check of the gateway alone sees a run in any worker.</p><p>A first start in a new environment can be slow (Python compiles the environment&#39;s modules on first import); <code>worker_start_seconds</code> gives it longer. With <code>worker_idle_seconds</code>, a worker with no request or socket in flight and no execution running in its process for that long is ended, and started again by the next request for it; a worker running an execution is never ended.</p><h2 id="routing" tabindex="-1">Routing <a class="header-anchor" href="#routing" aria-label="Permalink to &quot;Routing&quot;">​</a></h2><p>A request binds to a project and a user:</p><ul><li><code>X-Machinable-Project</code> (or <code>?project=</code>): the target project, restricted to the server&#39;s allowlist; defaults to the launch project.</li><li><code>X-Machinable-User</code>: attributes created interfaces (<code>created_by</code>); defaults to the OS user. A request signed by an <a href="#signing-requests-with-an-identity-provider">identity provider</a> is attributed to its verified identity instead.</li></ul><h2 id="signing-requests-with-an-identity-provider" tabindex="-1">Signing requests with an identity provider <a class="header-anchor" href="#signing-requests-with-an-identity-provider" aria-label="Permalink to &quot;Signing requests with an identity provider&quot;">​</a></h2><p>A shared <code>api_token</code> says nothing about who sent a request and never expires. Alternatively, a server can instead trust the access tokens from an OpenID Connect provider. In this case, the bearer token is a JWT signed by the issuer. To use this, install the extra and set the issuer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;machinable[oidc]&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">machinable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> machinable.server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oidc_issuer=https://id.example.org/realms/lab</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  oidc_audience=machinable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oidc_rules_file=/etc/machinable/rules.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --launch</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>oidc_issuer</code></td><td><code>None</code></td><td>issuer URL; its <code>/.well-known/openid-configuration</code> names the signing keys</td></tr><tr><td><code>oidc_audience</code></td><td><code>None</code></td><td>one or more accepted audiences (required): the token&#39;s <code>aud</code> must contain one; with several <code>aud</code> values, an <code>azp</code> present must be one of them, and <code>azp</code> alone never admits a token</td></tr><tr><td><code>oidc_rules</code></td><td><code>None</code></td><td>claim rules every token must pass (inline)</td></tr><tr><td><code>oidc_rules_file</code></td><td><code>None</code></td><td>a JSON file of rules, re-read when it changes</td></tr><tr><td><code>oidc_identity_claim</code></td><td><code>sub</code></td><td>the claim that names the caller</td></tr><tr><td><code>oidc_algorithms</code></td><td><code>RS256</code>, <code>ES256</code>, <code>EdDSA</code></td><td>accepted signature algorithms; <code>none</code> and HMAC are never accepted</td></tr><tr><td><code>oidc_leeway</code></td><td><code>60</code></td><td>clock skew in seconds allowed on <code>exp</code>, <code>nbf</code> and <code>iat</code></td></tr></tbody></table><p>The provider&#39;s keys are fetched at start and cached so a token naming an unknown key fetches them again, and a failed fetch keeps the last good keys. Only JWT access tokens are verified, and token issuance at sign in is left to the provider.</p><p><code>api_token</code> keeps working beside OIDC, so an operator&#39;s scripts and the <a href="#the-console">console</a> keep their token while people sign in. Source writes still need <code>source_token</code> (or <code>api_token</code>) in <code>X-Machinable-Source-Token</code>.</p><h3 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h3><p>A rule set is a list of rules that must all pass or may instead be <code>any_of</code> a list of rule sets, one of which must pass. A rule names a claim by its exact top-level name and one test (names may contain <code>/</code>, <code>:</code> and <code>.</code>, so there is no path syntax):</p><table tabindex="0"><thead><tr><th>Test</th><th>Passes when</th></tr></thead><tbody><tr><td><code>equals: v</code></td><td>the claim equals <code>v</code> (no type coercion: <code>&quot;311&quot;</code> is not <code>311</code>)</td></tr><tr><td><code>in: [v, …]</code></td><td>the claim equals one of them</td></tr><tr><td><code>contains: v</code></td><td>the claim is a list containing <code>v</code>, or an object with the key <code>v</code></td></tr><tr><td><code>present: true</code></td><td>the claim exists (<code>false</code>: it does not)</td></tr></tbody></table><p>A server for one lab, open to its admins and to one member:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;rules&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;claim&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://aws.amazon.com/tags/principal_tags/team&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;equals&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;311&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;any_of&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        [ { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;claim&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sub&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;equals&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;3950…196&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } ],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        [ { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;claim&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;urn:zitadel:iam:org:project:roles&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;contains&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;admin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ] }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><p>A rules file is re-read when it changes, so access changes without a restart. A rules file that is missing or does not parse refuses every OIDC request, with the reason in the server&#39;s log.</p><h3 id="clients-and-websockets" tabindex="-1">Clients and WebSockets <a class="header-anchor" href="#clients-and-websockets" aria-label="Permalink to &quot;Clients and WebSockets&quot;">​</a></h3><p>Clients send the token on every request as <code>Authorization: Bearer &lt;token&gt;</code>. A refused request is answered with 401 and <code>WWW-Authenticate: Bearer error=&quot;invalid_token&quot;</code>, with a short reason (<code>expired</code>, <code>wrong audience</code>, <code>rules</code>, …).</p><p>WebSocket upgrades need the token too (native clients set the <code>Authorization</code> header, browsers offer it as subprotocols <code>Sec-WebSocket-Protocol: bearer, &lt;token&gt;</code>). An upgrade without a valid token is refused before the socket opens (HTTP 403). A socket outlives its request, so the server closes a socket admitted by an OIDC token when the token&#39;s <code>exp</code> passes, with close code <code>4401</code>. In this case, the client refreshes its token and dials again. A socket admitted with the shared <code>api_token</code> is not closed.</p><p>Everything a signed request creates is attributed (<code>created_by</code>) to its verified identity claim, and <code>X-Machinable-User</code> is ignored. Interfaces can read the token&#39;s verified claims during the request as the read-only <code>Project.get().claims</code>.</p><h2 id="what-it-exposes" tabindex="-1">What it exposes <a class="header-anchor" href="#what-it-exposes" aria-label="Permalink to &quot;What it exposes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Family</th><th>Examples</th><th>Purpose</th></tr></thead><tbody><tr><td>Interfaces</td><td><code>POST /v1/interfaces</code>, <code>/search</code>, <code>/resolve</code>, <code>/{uuid}/provenance</code> <code>/data</code> <code>/related</code></td><td>create, search, dry-run, inspect</td></tr><tr><td>Executions</td><td><code>POST /v1/executions</code>, <code>GET /{uuid}</code>, <code>/output</code>, <code>/results</code></td><td>run lifecycle, output, declared results</td></tr><tr><td>Project</td><td><code>GET /v1/project[/{module}]</code>, <code>/remotes</code></td><td>module discovery + schema reflection</td></tr><tr><td>Source</td><td><code>GET/PUT/DELETE /v1/source/{path}</code></td><td>the opt-in, token-gated source-editing API</td></tr></tbody></table><p><code>POST /v1/executions</code> runs only the interfaces that are not yet cached. When every requested interface is already cached it returns at once without dispatching: the answer is the existing run-record of the first interface with <code>cached: true</code>, and <code>cached_uuids</code> lists the existing run-records of all requested interfaces.</p><p>The server looks before dispatching (see <a href="./advanced-execution.html#concurrent-dispatch">concurrent dispatch</a>), so several servers (or a server and scripts) over one storage folder run a request once. An interface another dispatcher holds is never waited on: when nothing was dispatched because some requested interfaces are running elsewhere (and the rest are cached), the answer is at once the run-record of the first interface, the one running elsewhere or the cached one, with <code>running_elsewhere: true</code>; <code>running_elsewhere_uuids</code> lists the runs held elsewhere and <code>cached_uuids</code> the cached ones. Follow the run with <code>GET /v1/executions/{uuid}</code> (or the executions WebSocket) as usual. The answer has indexed the run, so this server finds it, and while it is not finished here its status is read from its home: when the home is not the server&#39;s working copy (a bucket), each status read brings the home&#39;s status markers (small files, at most once a second per run) into the working copy, so the run reads live while the other machine beats, finished once it is (its catalog, output log and small results then come into the working copy, and its interface reads cached), and died when the other machine stops beating without finishing. A run whose home is a shared folder needs none of this, the folder being every server&#39;s working copy. A run finished elsewhere counts as cached.</p><p>A run&#39;s <a href="./results.html#declared-results">declared results</a> are served from its files, never by importing its interface, so a server without the interface&#39;s code or Python environment serves them: <code>GET /v1/executions/{uuid}/results</code> is the manifest (<code>uuid</code> a run-record or its interface), <code>GET /v1/executions/{uuid}/results/{name}</code> one result as JSON (a json result&#39;s <code>value</code>; a table&#39;s columns as <code>data</code>, rows <code>?start=&amp;stop=</code>; an array&#39;s or a ragged result&#39;s <code>?item=12</code> or <code>?start=&amp;stop=</code>, reading only the chunks those need; NaN as null), and the WebSocket <code>/v1/executions/{uuid}/results/ws</code> sends a <code>results</code> frame with the manifest at once and whenever it changes. A record whose home is a bucket is refreshed from it on each request (one small read), so a live run&#39;s results are current.</p><p>An interface can have several runs (dispatched again after <code>cached(False)</code>, say), so every API response returns the newest by creation: <code>POST /v1/interfaces/lifecycle</code> reports the newest run&#39;s status and its <code>execution_uuid</code>, an interface&#39;s <code>latest_execution_uuid</code> is the newest run, and <code>GET /v1/executions</code> and <code>GET /v1/interfaces/{uuid}/executions</code> list runs newest first (so <code>?limit=1</code> is the newest).</p><p>Config reflection is first-class: <code>GET /v1/project/{module}</code> returns the config fields and the <a href="./versions.html">version-method vocabulary</a> (signatures + docstrings), and <code>POST /v1/interfaces/resolve</code> dry-runs a compact version to its resolved config and CLI without materializing.</p><h2 id="the-console" tabindex="-1">The console <a class="header-anchor" href="#the-console" aria-label="Permalink to &quot;The console&quot;">​</a></h2><p><code>machinable console</code> attaches a terminal UI to a running server, local or remote. It is a pure API client, so everything it shows travels through the same contract as any other client:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;machinable[console]&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">machinable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> console</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                              # http://127.0.0.1:8000</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">machinable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> console</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://cluster:8000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SECRET</span></span></code></pre></div><p>The console browses and filters the record catalog, opens a record to inspect its resolved config, run history, and stored files, follows a live run&#39;s output, and cancels runs (<code>y</code> copies the record&#39;s CLI reproduction command). A server launched from a terminal attaches the console automatically when it is installed; set <code>console=true</code> to require it (launching fails with an install hint when it is missing) or <code>console=false</code> for a headless server.</p><p>Beyond browsing, the console drives the full loop:</p><ul><li><strong>Launch pad</strong> (<code>n</code>): pick a module, see its config fields and <code>~version</code> vocabulary, and type a version exactly like the <a href="./cli.html">CLI</a> (<code>~sgd lr=0.1 nested.k=2</code>). The preview resolves live, so typos surface as precise unknown-key errors, and an identity badge shows whether this configuration is a <code>draft</code> (launching runs it) or already <code>cached</code> (launching opens the existing record) before anything executes.</li><li><strong>Provenance</strong> (record detail tab): the record&#39;s provenance graph as a navigable tree of derivation, runs, and manifest edges; selecting a node jumps to that record.</li><li><strong>Call</strong> (record detail tab): invoke a method with the shared <code>method(args)</code> grammar (e.g. <code>summary(top=3)</code>) and read the returned value, with the equivalent <code>machinable … --method(args)</code> command shown for reproduction.</li><li><strong>Remotes</strong> (<code>R</code>): the project&#39;s declared remote modules, with the <a href="./storage.html#remotes-shareable-interfaces">inspect-before-import</a> workflow.</li><li><code>ctrl+p</code> opens the command palette; <code>?</code> shows the key reference.</li></ul><h2 id="the-full-contract" tabindex="-1">The full contract <a class="header-anchor" href="#the-full-contract" aria-label="Permalink to &quot;The full contract&quot;">​</a></h2><p>The server documents itself, so there is no static copy to keep in sync:</p><ul><li><strong>REST/OpenAPI</strong>: <code>GET /openapi.json</code> and the interactive <code>/docs</code>.</li><li><strong>WebSocket protocol</strong>: <code>GET /v1/protocol</code> returns a machine-readable description of the connect / call / stream / chunk-upload / event frames, which OpenAPI can&#39;t model.</li><li>Regenerate a markdown snapshot any time with <code>python -m machinable.api.docs</code>.</li></ul><p>For agent-facing usage, prefer the <a href="/mcp/overview.html">MCP server</a>, which wraps this API as curated tools, resources, and prompts.</p>`,59)])])}const k=t(i,[["render",n]]);export{u as __pageData,k as default};
